import { useState, type FormEvent } from 'react';
import { Button, Field, Form, Input, Select, Stack, Switch } from '@jinx-ui/react';

export type InterfaceLanguage = 'ru' | 'en';

export interface ProfileSettings {
  name: string;
  language: InterfaceLanguage;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS: ReadonlyArray<{ value: InterfaceLanguage; label: string }> = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'Английский' },
];

export default function ProfileSettingsForm({ onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<InterfaceLanguage>('ru');
